import { useEffect, useRef, useState } from 'react';
import type { FormEvent } from 'react';
import { useQueryClient } from '@tanstack/react-query';
import { SheetPanels } from '../../slots/defs/sheetPanels';
import { asString, useSearchParam } from '../../url/useSearchParam';

// The date this screen shows the sheet as of (search param `asof`, so it is this user's screen only). While it is
// set every request carries it (api/http.ts): every read answers as the sheet stood at the end of that date, with
// the date for its today, and every change is refused.
function AsOf() {
  const queryClient = useQueryClient();
  const [asof, setAsof] = useSearchParam('asof', asString);
  const [draft, setDraft] = useState('');
  const shown = useRef(asof);

  // Once the URL carries the new date, everything on screen is read again for it.
  useEffect(() => {
    if (shown.current === asof) return;
    shown.current = asof;
    void queryClient.resetQueries();
  }, [asof, queryClient]);

  const submit = (e: FormEvent) => {
    e.preventDefault();
    const date = draft.trim();
    if (/^\d{4}-\d{2}-\d{2}$/.test(date) && !Number.isNaN(Date.parse(date))) setAsof(date);
  };

  return (
    <form onSubmit={submit}>
      As of: <strong data-testid="sheet-asof">{asof}</strong>{' '}
      <input
        data-testid="asof-date"
        type="text"
        placeholder="yyyy-mm-dd"
        value={draft}
        onChange={(e) => setDraft(e.target.value)}
      />
      <button type="submit" data-testid="asof-set">
        Show as of
      </button>
      <button type="button" data-testid="asof-clear" onClick={() => setAsof(undefined)}>
        Show now
      </button>
    </form>
  );
}

export const contribution = SheetPanels.fill({ order: 1, Component: AsOf });
import { SheetPanels } from '../../slots/defs/sheetPanels';
import { usePeople } from './people';
import { useSheetToday } from '../sheet/sheet';
import { showDue, useRates } from '../rates/rates';
import { useCapCents, useFloorCents } from '../settings/settings';
import { personDueCents, useClaims, useLate } from '../claims/claims';

// A CSV value: wrapped in double quotes (any quote inside doubled) when it holds a comma, a quote or a line break.
const csvValue = (v: string) => (/[",\r\n]/.test(v) ? `"${v.replace(/"/g, '""')}"` : v);

// The button that downloads the people as CSV: everyone in list order, retired people included, with the grade in
// force on the sheet's today, the retired-from date (or nothing) and the due-total as their row shows it.
function ExportPeople({ sheet }: { sheet: string; user: string }) {
  const { data: people = [] } = usePeople(sheet);
  const { data: claims = [] } = useClaims(sheet);
  const { data: rates = [] } = useRates(sheet);
  const today = useSheetToday(sheet);
  const floor = useFloorCents(sheet);
  const cap = useCapCents(sheet);
  const late = useLate(sheet);

  const download = () => {
    const lines = [
      'name,grade,retired-from,due-total',
      ...people.map((p) =>
        [p.name, p.grade, p.retiredFrom ?? '', showDue(personDueCents(claims, rates, p, today, floor, late, cap))]
          .map(csvValue)
          .join(','),
      ),
    ];
    const url = URL.createObjectURL(new Blob([lines.map((l) => `${l}\n`).join('')], { type: 'text/csv' }));
    const a = document.createElement('a');
    a.href = url;
    a.download = `people-${sheet}.csv`;
    document.body.appendChild(a);
    a.click();
    a.remove();
    setTimeout(() => URL.revokeObjectURL(url), 1000);
  };

  return (
    <p>
      <button type="button" data-testid="export-people" onClick={download}>
        Export people (CSV)
      </button>
    </p>
  );
}

export const contribution = SheetPanels.fill({ order: 11, Component: ExportPeople });
import { SheetPanels } from '../../slots/defs/sheetPanels';
import { gradeOn, usePeople } from '../people/people';
import { claimRateOf, showDue, useRates } from '../rates/rates';
import { periodOf, usePeriods } from '../periods/periods';
import { useFloorCents } from '../settings/settings';
import { claimDueCents, useClaims, useLate } from './claims';

// A CSV value: wrapped in double quotes (any quote inside doubled) when it holds a comma, a quote or a line break.
const csvValue = (v: string) => (/[",\r\n]/.test(v) ? `"${v.replace(/"/g, '""')}"` : v);

// The button that downloads the claims as CSV: people in list order (retired people included), each person's claims
// oldest first, with the number, date, amount, due, status and period as the claim's row shows them.
function ExportClaims({ sheet }: { sheet: string; user: string }) {
  const { data: people = [] } = usePeople(sheet);
  const { data: claims = [] } = useClaims(sheet);
  const { data: rates = [] } = useRates(sheet);
  const { data: periods = [] } = usePeriods(sheet);
  const floor = useFloorCents(sheet);
  const late = useLate(sheet);

  const download = () => {
    const lines = [
      'person,number,date,amount,due,status,period',
      ...people.flatMap((p) =>
        // The claims are listed newest first; the export reads them oldest first.
        [...claims.filter((c) => c.person === p.id)].reverse().map((c) =>
          [
            p.name,
            String(c.periodNumber ?? c.number ?? ''),
            c.date,
            c.amount,
            showDue(claimDueCents(c, claimRateOf(rates, gradeOn(p, c.date), c), floor, late)),
            c.status,
            periodOf(periods, c.dueBy)?.name ?? '',
          ]
            .map(csvValue)
            .join(','),
        ),
      ),
    ];
    const url = URL.createObjectURL(new Blob([lines.map((l) => `${l}\n`).join('')], { type: 'text/csv' }));
    const a = document.createElement('a');
    a.href = url;
    a.download = `claims-${sheet}.csv`;
    document.body.appendChild(a);
    a.click();
    a.remove();
    setTimeout(() => URL.revokeObjectURL(url), 1000);
  };

  return (
    <p>
      <button type="button" data-testid="export-claims" onClick={download}>
        Export claims (CSV)
      </button>
    </p>
  );
}

export const contribution = SheetPanels.fill({ order: 12, Component: ExportClaims });
import { useQueryClient } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import { SheetPanels } from '../../slots/defs/sheetPanels';
import { poolsKey, poolsPath, type Pool } from './pools';

// A CSV value: wrapped in double quotes (any quote inside doubled) when it holds a comma, a quote or a line break.
const csvValue = (v: string) => (/[",\r\n]/.test(v) ? `"${v.replace(/"/g, '""')}"` : v);

// The button that downloads the pools as CSV: one line per member, pools in the order added and members in the
// order added, a pool member as pool:<name>, and the cut as its row shows it (empty when none). The pools are
// re-read first, so a change elsewhere (a retirement, a setting) is reflected, and the list shows the same.
function ExportPools({ sheet }: { sheet: string; user: string }) {
  const queryClient = useQueryClient();

  const download = async () => {
    const pools = await queryClient.fetchQuery({
      queryKey: poolsKey(sheet),
      queryFn: () => getJson<Pool[]>(poolsPath(sheet)),
      staleTime: 0,
    });
    const lines = [
      'pool,member,share,cut',
      ...pools.flatMap((pool) =>
        pool.members.map((m) =>
          [pool.name, m.memberPool !== null ? `pool:${m.memberPool}` : m.name, m.share, m.cut].map(csvValue).join(','),
        ),
      ),
    ];
    const url = URL.createObjectURL(new Blob([lines.map((l) => `${l}\n`).join('')], { type: 'text/csv' }));
    const a = document.createElement('a');
    a.href = url;
    a.download = `pools-${sheet}.csv`;
    document.body.appendChild(a);
    a.click();
    a.remove();
    setTimeout(() => URL.revokeObjectURL(url), 1000);
  };

  return (
    <p>
      <button type="button" data-testid="export-pools" onClick={() => void download()}>
        Export pools (CSV)
      </button>
    </p>
  );
}

export const contribution = SheetPanels.fill({ order: 9.9, Component: ExportPools });
